WITH v_sales_lines AS (SELECT 1 product_id, '2025-06-01' order_date,'store' channel,10000 net_cents,8000 cost_cents,500 discount_cents,200 refund_cents UNION ALL SELECT 2,'2025-06-01','store',9000,5000,100,0 UNION ALL SELECT 3,'2025-06-01','store',8000,7600,100,0 UNION ALL SELECT 4,'2025-06-01','store',7000,4000,0,0 UNION ALL SELECT 5,'2025-06-01','store',6000,3000,0,0 UNION ALL SELECT 6,'2025-06-01','store',5000,4000,0,0 UNION ALL SELECT 7,'2025-06-01','store',4000,3000,0,0 UNION ALL SELECT 8,'2025-06-01','store',0,0,0,100),
a AS (SELECT product_id,SUM(net_cents) net,SUM(cost_cents) cost,SUM(discount_cents) discount,SUM(refund_cents) refund FROM v_sales_lines WHERE channel='store' AND order_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY product_id),
b AS (SELECT *,NTILE(4) OVER(ORDER BY net DESC,product_id) bucket FROM a) SELECT product_id,net,cost FROM a ORDER BY net;

WITH v_sales_lines AS (SELECT 1 product_id, '2025-06-01' order_date,'store' channel,10000 net_cents,8000 cost_cents,500 discount_cents,200 refund_cents UNION ALL SELECT 2,'2025-06-01','store',9000,5000,100,0 UNION ALL SELECT 3,'2025-06-01','store',8000,7600,100,0 UNION ALL SELECT 4,'2025-06-01','store',7000,4000,0,0 UNION ALL SELECT 5,'2025-06-01','store',6000,3000,0,0 UNION ALL SELECT 6,'2025-06-01','store',5000,4000,0,0 UNION ALL SELECT 7,'2025-06-01','store',4000,3000,0,0 UNION ALL SELECT 8,'2025-06-01','store',0,0,0,100),
a AS (SELECT product_id,SUM(net_cents) net,SUM(cost_cents) cost,SUM(discount_cents) discount,SUM(refund_cents) refund FROM v_sales_lines WHERE channel='store' AND order_date BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY product_id),
b AS (SELECT *,NTILE(4) OVER(ORDER BY net DESC,product_id) bucket FROM a) SELECT product_id,bucket,ROUND(100.0*(net-cost)/NULLIF(net,0),2) AS margin_pct FROM b ORDER BY bucket DESC, margin_pct DESC;

